TARGET_ANSWERS = 'BCADBBCADC'
for i, (prompt, options, answer, explanation, strategy) in enumerate(DATA, 1):
    path = ROOT / "questions/science" / f"question-science-content-mb-iv-1-{i}.json"
    item = json.loads(path.read_text())
    correct = options[ord(answer) - 65]
    target = TARGET_ANSWERS[i - 1]
    distractors = [text for option_index, text in enumerate(options) if option_index != ord(answer) - 65]
    position = ord(target) - 65
    arranged = distractors[:position] + [correct] + distractors[position:]
    item.update({"prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(arranged)], "answer": {"value": target, "explanation": f"{explanation} 正確答案為選項 {target}：「{correct}」。"}, "solutionStrategy": strategy, "solutionSteps": ["圈出生物技術、目標效益、可能風險、對照組與環境尺度。", "檢查是否同時比較效益與非目標效應，並有重複、監測與替代解釋。", f"套用本題原理：{explanation}", f"排除只看單一成功指標、忽略逸散或把未知當安全的選項，答案為「{correct}」（選項 {target}）。", "回查結論是否符合生命週期、空間尺度、時間延遲與治理條件。"], "examPatternRefs": REFS, "reviewStatus": "draft", "updatedAt": "2026-09-13"})
    path.write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n")
